"""policy.ini (docs/policy.md)."""

import re
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {"max_size": None, "max_age": None, "naming": "numbered", "offset": (0, 0),
           "compress_after": 1, "keep": 5, "keep_days": None}

_NUM = re.compile(r"[0-9]+\Z")
_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DUR = re.compile(r"([0-9]+)([mhd])\Z")
_OFF = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_SECTION = re.compile(r"\[(.*)\]\Z")


def _bad(msg):
    raise DataError("policy", f"policy.ini: {msg}")


def _value(key, v):
    if key == "max_size":
        if v == "off":
            return None
        m = _SIZE.match(v)
        if not m:
            _bad(f"bad size {v}")
        return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]
    if key == "max_age":
        if v == "off":
            return None
        m = _DUR.match(v)
        if not m:
            _bad(f"bad duration {v}")
        return int(m.group(1)) * {"m": 60, "h": 3600, "d": 86400}[m.group(2)]
    if key == "naming":
        if v not in ("numbered", "dated"):
            _bad(f"bad naming {v}")
        return v
    if key == "offset":
        m = _OFF.match(v)
        if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
            _bad(f"bad offset {v}")
        s = -1 if m.group(1) == "-" else 1
        return (s * int(m.group(2)), s * int(m.group(3)))
    if key == "compress_after":
        if not _NUM.match(v):
            _bad(f"bad number {v}")
        return int(v)
    if key == "keep":
        if not _NUM.match(v) or int(v) < 1:
            _bad(f"bad keep {v}")
        return int(v)
    if key == "keep_days":
        if v == "off":
            return None
        if not _NUM.match(v) or int(v) < 1:
            _bad(f"bad keep_days {v}")
        return int(v)
    _bad(f"unknown key {key}")


def load(path: Path):
    """Returns (defaults dict, {stream: dict of its own settings})."""
    if not path.exists():
        return {}, {}
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"policy.ini: {e}") from None
    defaults, per = None, {}
    cur = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        m = _SECTION.match(line)
        if m:
            title = m.group(1)
            if title == "defaults":
                if defaults is not None:
                    _bad("defaults twice")
                defaults = cur = {}
            elif title.startswith("stream ") and streams.valid(title[7:]):
                n = title[7:]
                if n in per:
                    _bad(f"section {n} twice")
                per[n] = cur = {}
            else:
                _bad(f"unknown section {title}")
            continue
        if cur is None or "=" not in line:
            _bad(f"bad line {line}")
        k, v = (s.strip() for s in line.split("=", 1))
        if k in cur:
            _bad(f"key {k} twice")
        cur[k] = _value(k, v)
    return defaults or {}, per


def settings(defaults, per, name):
    out = dict(BUILTIN)
    out.update(defaults)
    out.update(per.get(name, {}))
    return out
