"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import policy as policy_mod
from logkeep import state as state_mod
from logkeep import streams
from logkeep.errors import DataError, Refused

_ISO = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})T([0-9]{2}:[0-9]{2}:[0-9]{2})(\.[0-9]+)?(Z|[+-][0-9]{2}:?[0-9]{2})\Z")
_LEGACY = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")
_DAY = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([0-9]+))?\Z")
_N = re.compile(r"[1-9][0-9]*\Z")


def parse_iso(text):
    m = _ISO.match(text)
    if not m:
        return None
    tz = m.group(4)
    if tz == "Z":
        tz = "+00:00"
    elif ":" not in tz:
        tz = tz[:3] + ":" + tz[3:]
    frac = (m.group(3) or "")[:7]
    try:
        return datetime.fromisoformat(f"{m.group(1)}T{m.group(2)}{frac}{tz}")
    except ValueError:
        return None


def parse_state_time(text):
    if not isinstance(text, str):
        return None
    if _LEGACY.match(text):
        try:
            return datetime.fromisoformat(text.replace(" ", "T")).replace(tzinfo=timezone.utc)
        except ValueError:
            return None
    return parse_iso(text)


def _fmt(t):
    return t.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _validate_entry(name, entry):
    if "opened" in entry and parse_state_time(entry["opened"]) is None:
        raise DataError("state", f"{name}: bad opened")
    if "rotations" in entry:
        r = entry["rotations"]
        if not isinstance(r, int) or isinstance(r, bool) or r < 0:
            raise DataError("state", f"{name}: bad rotations")
    if "archives" in entry:
        a = entry["archives"]
        if not isinstance(a, dict):
            raise DataError("state", f"{name}: bad archives")
        for k, v in a.items():
            if parse_state_time(v) is None:
                raise DataError("state", f"{name}: bad archive time {k}")


def _find_archives(logs, name, naming):
    """List of dicts: file, key (age key, bigger = newer), gz, base."""
    out = {}
    prefix = f"{name}.log."
    if not logs.is_dir():
        return []
    for p in logs.iterdir():
        fn = p.name
        if not fn.startswith(prefix) or not p.is_file():
            continue
        rest = fn[len(prefix):]
        gz = rest.endswith(".gz")
        if gz:
            rest = rest[:-3]
        if naming == "numbered":
            if not _N.match(rest):
                continue
            key = -int(rest)
            place = rest
            day, k = None, None
        else:
            m = _DAY.match(rest)
            if not m:
                continue
            try:
                day = date.fromisoformat(m.group(1))
            except ValueError:
                continue
            if m.group(2) is None:
                k = 1
            else:
                if not re.match(r"[1-9][0-9]*\Z", m.group(2)) or int(m.group(2)) < 2:
                    continue
                k = int(m.group(2))
            key = (day.toordinal(), k)
            place = rest
        if place in out:
            raise DataError("archives", f"{fn}: same place as {out[place]['file']}")
        out[place] = {"file": fn, "key": key, "gz": gz, "base": prefix + rest, "day": day, "k": k,
                      "path": p, "new": False}
    return list(out.values())


def run(ctx, streams_arg, dry, force):
    defaults, per = policy_mod.load(ctx.policy_path)
    st = ctx.state
    data = ctx.data
    active = streams.active(data)
    existing = set(active) | set(per)
    for n in existing:
        if n in st["streams"]:
            _validate_entry(n, st["streams"][n])
    if streams_arg:
        names = sorted(set(streams_arg))
        for n in names:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
    else:
        names = sorted(existing)
    logs = streams.logs_dir(data)
    now = ctx.now

    plans = []
    for n in names:
        s = policy_mod.settings(defaults, per, n)
        arch = _find_archives(logs, n, s["naming"])
        arch.sort(key=lambda a: a["key"], reverse=True)
        plans.append((n, s, arch))

    out = []
    writes = []  # (kind, ...)
    new_state = {}
    tot_rot = tot_rem = tot_comp = 0
    for n, s, arch in plans:
        entry = st["streams"].get(n, {})
        times = entry.get("archives", {}) if isinstance(entry.get("archives", {}), dict) else {}
        logp = streams.log_path(data, n)
        reason = None
        if not logp.is_file():
            what = "no log"
        else:
            size = logp.stat().st_size
            if size == 0:
                what = "empty"
            else:
                if force:
                    reason = "forced"
                elif s["max_size"] is not None and size >= s["max_size"]:
                    reason = "size"
                elif s["max_age"] is not None:
                    if "opened" in entry:
                        opened = parse_state_time(entry["opened"])
                    else:
                        with logp.open("rb") as f:
                            first = f.readline()
                        opened = None
                        try:
                            txt = first.decode("utf-8")
                        except UnicodeDecodeError:
                            txt = ""
                        txt = txt.rstrip("\n")
                        if " " in txt:
                            opened = parse_iso(txt.split(" ", 1)[0])
                    if opened is not None and (now - opened).total_seconds() >= s["max_age"]:
                        reason = "age"
                what = f"rotate ({reason})" if reason else "not due"
        out.append(f"{n}: {what}")
        rotated = reason is not None
        if rotated:
            if s["naming"] == "numbered":
                new = {"file": f"{n}.log.1", "base": f"{n}.log.1", "gz": False, "new": True, "key": 1}
                # existing ones shift; handled by renumbering below
                arch = [new] + arch
            else:
                tz = timezone(timedelta(hours=s["offset"][0], minutes=s["offset"][1]))
                day = now.astimezone(tz).date()
                ks = [a["k"] for a in arch if a["day"] == day]
                k = max(ks) + 1 if ks else None
                base = f"{n}.log.{day.isoformat()}" + (f".{k}" if k else "")
                new = {"file": base, "base": base, "gz": False, "new": True,
                       "key": (day.toordinal(), k or 1), "day": day, "k": k or 1}
                arch = sorted(arch + [new], key=lambda a: a["key"], reverse=True)
        keep_secs = None if s["keep_days"] is None else timedelta(days=s["keep_days"])
        remaining, removed = [], []
        for i, a in enumerate(arch, 1):
            drop = i > s["keep"]
            if not drop and keep_secs is not None:
                if a["new"]:
                    t = now
                else:
                    t = parse_state_time(times[a["file"]]) if a["file"] in times else None
                if t is not None and now - t >= keep_secs:
                    drop = True
            (removed if drop else remaining).append(a)
        arch_state = {}
        lines = []
        for i, a in enumerate(remaining, 1):
            comp = (not a["gz"]) and i > s["compress_after"]
            gz = a["gz"] or comp
            if s["naming"] == "numbered":
                final = f"{n}.log.{i}" + (".gz" if gz else "")
            else:
                final = a["base"] + (".gz" if gz else "")
            a["final"], a["comp"] = final, comp
            if comp:
                tot_comp += 1
            if a["new"]:
                lines.append(f"  new {final}")
                arch_state[final] = _fmt(now)
            else:
                lines.append(f"  {final} <- {a['file']}" if final != a["file"] else f"  {final}")
                if a["file"] in times:
                    arch_state[final] = times[a["file"]]
        out.extend(lines)
        for a in removed:
            out.append(f"  remove {a['file'] if not a['new'] else a['base']}" if False else f"remove {a['file']}")
        # indentation: spec shows removes indented by two spaces
        if removed:
            for _ in removed:
                out.pop()
            for a in removed:
                out.append(f"  remove {a['file']}")
        tot_rem += len(removed)
        tot_rot += 1 if rotated else 0
        writes.append((n, rotated, remaining, removed))
        ne = {}
        if rotated:
            ne["opened"] = _fmt(now)
        elif "opened" in entry:
            ne["opened"] = entry["opened"]
        ne["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        ne["archives"] = arch_state
        new_state[n] = ne
    out.append(f"{tot_rot} rotated, {tot_rem} removed, {tot_comp} compressed")
    if dry:
        out.append("dry run: nothing written")
        return out

    # read everything first
    jobs = []
    for n, rotated, remaining, removed in writes:
        logp = streams.log_path(data, n)
        newcontent = logp.read_bytes() if rotated else None
        for a in remaining:
            if a["new"]:
                content = newcontent
            elif a["final"] != a["file"]:
                content = a["path"].read_bytes()
            else:
                continue
            if a["comp"]:
                content = gzip.compress(content, mtime=0)
            jobs.append((a["final"], content))
        for a in removed:
            if not a["new"]:
                jobs.append((None, a["path"]))
    for n, rotated, remaining, removed in writes:
        for a in remaining:
            if not a["new"] and a["final"] != a["file"]:
                a["path"].unlink()
        for a in removed:
            if not a["new"]:
                a["path"].unlink()
    for final, content in jobs:
        if final is not None:
            (logs / final).write_bytes(content)
    for n, rotated, remaining, removed in writes:
        if rotated:
            streams.log_path(data, n).write_bytes(b"")
    doc = dict(st)
    doc["streams"] = dict(st["streams"])
    doc["streams"].update(new_state)
    state_mod.save(ctx.state_path, doc)
    return out
